import{_ as t,a0 as r,w as o,s as d,I as e,x as a,a1 as i,A as l,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"如何在CentOS中创建辅域名服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在CentOS中创建辅域名服务器 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在CentOS中创建辅域名服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在CentOS中创建辅域名服务器 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/How to set up a secondary DNS server in CentOS","title":"如何在CentOS中创建辅域名服务器","tag":"201405","desc":""},"relativePath":"201405/How to set up a secondary DNS server in CentOS.md","filePath":"[post].md"}'),h={name:"201405/How to set up a secondary DNS server in CentOS.md"};function c(g,s,k,u,b,m){const n=r("Link");return o(),d("div",null,[s[17]||(s[17]=e("h1",{id:"如何在centos中创建辅域名服务器",tabindex:"-1"},[a("如何在CentOS中创建辅域名服务器 "),e("a",{class:"header-anchor",href:"#如何在centos中创建辅域名服务器","aria-label":"Permalink to “如何在CentOS中创建辅域名服务器”"},"​")],-1)),e("p",null,[s[1]||(s[1]=a("在",-1)),i(n,{href:"http://linux.cn/article-3092-1.html"},{default:l(()=>[...s[0]||(s[0]=[a("上篇教程",-1)])]),_:1}),s[2]||(s[2]=a("里，我们为一个测试域exmample.tst创建了一个主域名服务器（ns1）。在本篇中，我们会在CentOS中使用bind包为相同的域创建一个辅域名服务器（ns2）。",-1))]),s[18]||(s[18]=p('<p>当创建一个辅DNS服务器的时候，下面的因素需要仔细考虑。</p><ul><li>在辅域名服务器中，你不需要手动创建正向和反向区域文件。这些区域文件会定期从主域名服务器上面同步。</li><li>当主域名服务器上的任何区域文件被修改的时候，&#39;serial&#39;参数也应当被更新。只有当主服务器上面区域文件的serial被修改之后，辅DNS服务器才会进行同步。</li></ul><p>我们假设辅DNS服务器的IP地址是172.16.1.4。让我们来进行安装。</p><h3 id="设置主机名" tabindex="-1">设置主机名 <a class="header-anchor" href="#设置主机名" aria-label="Permalink to “设置主机名”">​</a></h3><p>就像主域名服务器一样，辅域名服务器的主机名也应当是一个完全限定域名（FQDN）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vim /etc/sysconfig/network</span></span></code></pre></div><blockquote><p>HOSTNAME=ns2.example.tst</p></blockquote><p>注意，在该文件中设置的主机名在服务器启动的时候会被使用。因此，如果你在系统启动之后修改该文件，修改结果不会立刻生效。下面的命令可以用来在系统运行的时候修改并及时生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># hostname ns2.example.tst</span></span></code></pre></div><p>设置之后，可以用下面的命令来查看主机名称。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># hostname</span></span></code></pre></div><hr><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ns2.example.tst</span></span></code></pre></div><p>在进行下面的步骤之前，确保所有三台服务器的主机名称已经被正确设置。</p><h3 id="安装软件包" tabindex="-1">安装软件包 <a class="header-anchor" href="#安装软件包" aria-label="Permalink to “安装软件包”">​</a></h3>',15)),e("p",null,[s[4]||(s[4]=a("就像",-1)),i(n,{href:"http://linux.cn/article-3092-1.html"},{default:l(()=>[...s[3]||(s[3]=[a("主服务器",-1)])]),_:1}),s[5]||(s[5]=a("一样，配置一台辅域名服务器可以使用chroot或者不用。必须的软件包可以使用yum轻松安装。",-1))]),s[19]||(s[19]=p(`<p>不使用 chroot:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install bind</span></span></code></pre></div><p>使用 chroot:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install bind-chroot</span></span></code></pre></div><h3 id="为区域文件的传输准备配置文件" tabindex="-1">为区域文件的传输准备配置文件 <a class="header-anchor" href="#为区域文件的传输准备配置文件" aria-label="Permalink to “为区域文件的传输准备配置文件”">​</a></h3><p>在CentOS中使用bind创建域名服务器后，默认设置允许所有的区域文件被任意服务器同步。安全起见，我们需要配置主域名服务器，只允许它允许辅域名服务器进行同步。</p><h4 id="_1-主域名服务器" tabindex="-1">1. 主域名服务器 <a class="header-anchor" href="#_1-主域名服务器" aria-label="Permalink to “1. 主域名服务器”">​</a></h4><p>不使用chroot：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    # vim /etc/named.conf</span></span></code></pre></div><p>使用chroot：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    # vim /var/named/chroot/etc/named.conf</span></span></code></pre></div><hr><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zone &quot;example.tst&quot; IN {</span></span>
<span class="line"><span>    type master;</span></span>
<span class="line"><span>    file &quot;example-fz&quot;; ## 文件example-fz在主域名服务器上 ##</span></span>
<span class="line"><span>    allow-update { none; };</span></span>
<span class="line"><span>    allow-transfer {172.16.1.4; }; ## 允许辅域名服务器进行传输 ##</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>zone &quot;1.16.172.in-addr.arpa&quot; IN {</span></span>
<span class="line"><span>    type master;</span></span>
<span class="line"><span>    file &quot;rz-172-16-1&quot;; ##文件rz-172-16-1在主域名服务器上##</span></span>
<span class="line"><span>    allow-update { none; };</span></span>
<span class="line"><span>    allow-transfer {172.16.1.4; }; ## 允许辅域名服务器进行传输 ##</span></span>
<span class="line"><span>};</span></span></code></pre></div><h4 id="_2-辅域名服务器" tabindex="-1">2. 辅域名服务器 <a class="header-anchor" href="#_2-辅域名服务器" aria-label="Permalink to “2. 辅域名服务器”">​</a></h4><p>软件安装后提供的默认配置文件就可以用来配置辅域名服务器。但是，我们使用会使用另外一个实例配置文件来进行配置，因为这样便于调整。</p><p>不使用chroot：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cp /usr/share/doc/bind-9.8.2/sample/etc/named.rfc1912.zones /etc/named.conf</span></span></code></pre></div><p>使用chroot：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cp /usr/share/doc/bind-9.8.2/sample/etc/named.rfc1912.zones /var/named/chroot/etc/named.conf</span></span></code></pre></div><p>当执行完上面的命令进行文件拷贝后，添加下面的内容到刚才那个拷贝后的文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>options {</span></span>
<span class="line"><span>        directory &quot;/var/named&quot;;</span></span>
<span class="line"><span>        forwarders {8.8.8.8; };</span></span>
<span class="line"><span></span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>zone &quot;example.tst&quot; IN {</span></span>
<span class="line"><span>        type slave;  ## 该主机为辅域名服务器 ##</span></span>
<span class="line"><span>        file &quot;example-fz&quot;; ## 这个文件会被自动创建 ##</span></span>
<span class="line"><span>        //allow-update { none; };</span></span>
<span class="line"><span>        allow-transfer {172.16.1.3; };  ## 定义必要时进行从其传输的主域名服务器 ##</span></span>
<span class="line"><span>        masters {172.16.1.3; }; ## 定义主域名服务器 ##</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>zone &quot;1.16.172.in-addr.arpa&quot; IN {</span></span>
<span class="line"><span>        type slave; ## 该主机被定义为辅域名服务器 ##</span></span>
<span class="line"><span>        file &quot;rz-172-16-1&quot;; ## 这个文件会被自动创建 ##</span></span>
<span class="line"><span>//      allow-update { none; };</span></span>
<span class="line"><span>        allow-transfer {172.16.1.3; };  ## 定义主域名服务器 ##</span></span>
<span class="line"><span>        masters {172.16.1.3; };</span></span>
<span class="line"><span>};</span></span></code></pre></div><h3 id="结束工作" tabindex="-1">结束工作 <a class="header-anchor" href="#结束工作" aria-label="Permalink to “结束工作”">​</a></h3><p>为了确保没有权限相关的问题，我们需要做如下调整。</p><p>不使用chroot：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod 770 /var/named/</span></span></code></pre></div><p>使用chroot，你需在named服务启动后按照下面的命令修改权限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chmod 770 /var/named/chroot/var/named</span></span></code></pre></div><p>现在万事俱备，我们可以重启named服务。或者，确保named服务已经被加到了开始列表中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># service named restart</span></span>
<span class="line"><span># chkconfig named on</span></span></code></pre></div><p>如果不出意外，辅域名服务器应该会向主域名服务器请求一个区域的传输，并且产生自己的/var/named目录。日志文件/var/log/messages会包含一些named服务的有用信息，包括区域文件传输过程中的信息。</p><h3 id="测试一个辅域名服务器" tabindex="-1">测试一个辅域名服务器 <a class="header-anchor" href="#测试一个辅域名服务器" aria-label="Permalink to “测试一个辅域名服务器”">​</a></h3><p>我们可以使用dig或者nslookup进行DNS测试操作。在本篇教程中我们会使用nslookup来进行演示。必要的软件包可以通过yum进行安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install bind-utils</span></span>
<span class="line"><span># nslookup</span></span></code></pre></div><hr><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; server 172.16.1.4</span></span>
<span class="line"><span>Default server:     172.16.1.4</span></span>
<span class="line"><span>Address:            172.16.1.4#53</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; example.tst</span></span>
<span class="line"><span>Server:             172.16.1.4</span></span>
<span class="line"><span>Address:    172.16.1.4#53</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name:       example.tst</span></span>
<span class="line"><span>Address:    172.16.1.3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; set type=mx</span></span>
<span class="line"><span>&gt; example.tst</span></span>
<span class="line"><span>Server:             172.16.1.4</span></span>
<span class="line"><span>Address:            172.16.1.4#53</span></span>
<span class="line"><span></span></span>
<span class="line"><span>example.tst         mail exchanger = 10 mail.example.tst.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; exit</span></span></code></pre></div><h3 id="排错提示" tabindex="-1">排错提示 <a class="header-anchor" href="#排错提示" aria-label="Permalink to “排错提示”">​</a></h3><ol><li><p>我们无需在辅域名服务器上创建任何区域文件。所有的区域文件都会与主域名服务器进行同步。</p></li><li><p>辅域名服务器上的named服务会定期与主服务器进行同步。如果你想来一次及时的同步，可以使用命令 <code>rncd retransfer &lt;FQDN&gt;</code>。如下：</p></li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># rndc retransfer example.tst</span></span></code></pre></div><ol start="3"><li><p>只有当主服务器上区域文件的serial数字被修改变大的时候，辅域名服务器才会进行更新。</p></li><li><p>确保用户named可以对文件夹/var/named或者/var/named/chroot/var/named（使用chroot的情况下）进行写操作。</p></li><li><p>/var/log/messages会包含有用的信息。</p></li><li><p>我已经将SELinux关闭了。</p></li><li><p>确保防火墙对UDP53端口开放。</p></li></ol><p>希望这个可以帮到你。</p><hr>`,41)),e("p",null,[s[7]||(s[7]=a("via: ",-1)),i(n,{href:"http://xmodulo.com/2014/04/secondary-dns-server-centos.html"},{default:l(()=>[...s[6]||(s[6]=[a("http://xmodulo.com/2014/04/secondary-dns-server-centos.html",-1)])]),_:1})]),e("p",null,[s[10]||(s[10]=a("译者：",-1)),i(n,{href:"https://github.com/zzlyzq"},{default:l(()=>[...s[8]||(s[8]=[a("zzlyzq",-1)])]),_:1}),s[11]||(s[11]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[14]||(s[14]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[12]||(s[12]=[a("LCTT",-1)])]),_:1}),s[15]||(s[15]=a(" 原创翻译，",-1)),i(n,{href:"http://linux.cn/"},{default:l(()=>[...s[13]||(s[13]=[a("Linux中国",-1)])]),_:1}),s[16]||(s[16]=a(" 荣誉推出",-1))])])}const C=t(h,[["render",c]]);export{v as __pageData,C as default};
